import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from '../supabase';
import { useSeriesData } from '../userSeriesData';
import { SeriesSection } from './SeriesSection';
import { DecoratedAvatar } from '../Components/DecoratedAvatar';
import { Menu, X, Bell, CheckCircle, Play, RefreshCw } from 'lucide-react';
import { useTelemetry } from '../Components/useTelemetry';
import { FeatureTutorialModal, TutorialHelpButton } from '../Components/FeatureTutorialModal';
import {
  isChapterReleasedForUser,
  isInPlusEarlyAccessWindow,
  getOneShotWednesdaySeries
} from '../oneshotWednesday';

const CLOUDFLARE_BASE_URL = 'https://pub-180171f859f64aa7aadb7001a6b96e65.r2.dev';

// Checks if a chapter or series is within 7 days of its official release timestamp (publish_at || created_at)
const isNewRelease = (publishAt?: string | null, createdAt?: string | null) => {
  const effectiveDate = publishAt || createdAt;
  if (!effectiveDate) return false;
  const releaseTime = new Date(effectiveDate).getTime();
  const now = Date.now();
  return releaseTime <= now && now - releaseTime < 7 * 24 * 60 * 60 * 1000;
};

// Checks if a Vault item / Series / Creator / Character was added within the last N days
const isRecentAddition = (createdAt?: string | null, days = 14) => {
  if (!createdAt) return false;
  const createdTime = new Date(createdAt).getTime();
  if (isNaN(createdTime)) return false;
  const now = Date.now();
  return createdTime <= now && now - createdTime < days * 24 * 60 * 60 * 1000;
};

// Checks if a scheduled item is live yet
const isReleasedYet = (publishAt?: string | null) => {
  if (!publishAt) return true;
  return new Date(publishAt).getTime() <= Date.now();
};

let memHeroSlides: any = null;
let memHomeSections: any = null;
let memLatestChapters: any = null;
let memRecentReads: any = null;
let memNotifications: any = null;
let memRecentCreators: any = null;
let memRecentCharacters: any = null;
let lastHomeFetchTime = 0;

const homeTutorialSlides = [
  {
    id: 'am-console',
    title: 'The AM Console',
    description:
      'Your personal command center. Navigate the app, track your weekly Hype balance, and access the shop. Tap your avatar in the center to access your profile, and customize the console by unlocking new artwork and glowing border frames.',
    mediaUrl:
      'https://pub-180171f859f64aa7aadb7001a6b96e65.r2.dev/homepage-graphic-assets/Tutorial%20Videos/AMConsole.mp4'
  },
  {
    id: 'user-profile',
    title: 'Your Profile',
    description:
      'Track your reading stats, equip your top 5 favorite series, and show off your Global Fandom Rank. Customize your digital loadout to flex your achievements on the leaderboards.',
    mediaUrl:
      'https://pub-180171f859f64aa7aadb7001a6b96e65.r2.dev/homepage-graphic-assets/Tutorial%20Videos/UserProfileloadout.mp4'
  }
];

export const HomePage = ({
  onNavigate,
  onLoginClick,
  onMenuToggle,
  currentUser,
  userTier
}: any) => {
  const {
    seriesList = [],
    vaultAvatars = [],
    cardSkins = [],
    vaultFrames = [],
    isLoading
  } = useSeriesData();
  const { trackEvent } = useTelemetry(currentUser?.id);

  const [currentSlide, setCurrentSlide] = useState(0);
  const [heroSlides, setHeroSlides] = useState<any[]>(memHeroSlides || []);
  const [homeSections, setHomeSections] = useState<any[]>(memHomeSections || []);
  const [latestChapters, setLatestChapters] = useState<any[]>(memLatestChapters || []);
  const [recentCreators, setRecentCreators] = useState<any[]>(memRecentCreators || []);
  const [recentCharacters, setRecentCharacters] = useState<any[]>(memRecentCharacters || []);
  const [isLoadingSlides, setIsLoadingSlides] = useState(!memHeroSlides);

  const [recentReads, setRecentReads] = useState<any[]>(memRecentReads || []);
  const [notifications, setNotifications] = useState<any[]>(memNotifications || []);
  const [showNotifications, setShowNotifications] = useState(false);
  const [dismissedNotifs, setDismissedNotifs] = useState<string[]>([]);

  const [forceTutorial, setForceTutorial] = useState(false);
  const [isRefreshingApp, setIsRefreshingApp] = useState(false);
  const [nowTick, setNowTick] = useState(() => Date.now());

  const isPlusSubscriber = userTier === 'premium' || Boolean(currentUser?.is_premium);

  // Re-evaluate scheduled drops every 30 seconds locally in browser memory (zero database load!)
  useEffect(() => {
    const interval = setInterval(() => setNowTick(Date.now()), 30000);
    return () => clearInterval(interval);
  }, []);

  // --- 1-TAP UNIVERSAL HARD REFRESH (CLEARS IOS/PWA CACHE & SERVICE WORKERS) ---
  const handleHardRefresh = async () => {
    if (isRefreshingApp) return;
    setIsRefreshingApp(true);

    try {
      memHeroSlides = null;
      memHomeSections = null;
      memLatestChapters = null;
      memRecentReads = null;
      memNotifications = null;
      memRecentCreators = null;
      memRecentCharacters = null;
      lastHomeFetchTime = 0;

      if ('serviceWorker' in navigator) {
        const registrations = await navigator.serviceWorker.getRegistrations();
        await Promise.all(registrations.map(reg => reg.unregister()));
      }

      if ('caches' in window) {
        const cacheNames = await window.caches.keys();
        await Promise.all(cacheNames.map(name => window.caches.delete(name)));
      }
    } catch (err) {
      console.error('Cache clear error:', err);
    }

    const url = new URL(window.location.href);
    url.searchParams.set('v', Date.now().toString());
    window.location.replace(url.toString());
  };

  // Filter Latest Chapters: must be published, release timestamp must have arrived (or 12h early for PLUS), and parent series must be live
  const visibleLatestChapters = useMemo(() => {
    return latestChapters
      .filter(chapter => {
        if (!chapter.is_published) return false;
        if (!isChapterReleasedForUser(chapter.publish_at, isPlusSubscriber)) return false;
        const seriesData = seriesList.find((s: any) => s.slug === chapter.series_slug);
        return seriesData && !seriesData.is_hidden && isReleasedYet(seriesData.publish_at);
      })
      .sort((a, b) => {
        const releaseA = new Date(a.publish_at || a.created_at || 0).getTime();
        const releaseB = new Date(b.publish_at || b.created_at || 0).getTime();
        return releaseB - releaseA;
      })
      .slice(0, 10);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [latestChapters, seriesList, nowTick, isPlusSubscriber]);

  // --- SELF-SYNCING NOTIFICATIONS ENGINE ---
  // Automatically syncs:
  // 1. Explicit rows from `app_notifications` (verified against live series/chapters)
  // 2. Live Chapters (`visibleLatestChapters`) & New Series (`seriesList`)
  // 3. New Creators Added ("Meet the Creator!" -> jumps to creator on CreatorsPage)
  // 4. New Characters Added ("New Character Unlocked!" -> opens dossier modal on CharacterRoster)
  // 5. New Card Skins, New Avatars, and New Border Frames (-> opens UserProfile loadout tab)
  // 6. One-Shot Wednesdays (OSW Wednesdays)
  // 7. Friday Reminders for Saturday 12-Hour Early Access
  const visibleNotifications = useMemo(() => {
    const chaptersById = new Map<string, any>();
    latestChapters.forEach((ch: any) => {
      chaptersById.set(String(ch.id), ch);
    });

    const unifiedMap = new Map<string, any>();
    const isDismissed = (key: string) => dismissedNotifs.includes(key);

    // 1. Process explicit rows from `app_notifications`
    notifications.forEach((n: any) => {
      if (!n || !n.id || !n.title) return;

      const sourceKey = String(n.source_key || '');
      if (sourceKey.startsWith('chapter_')) {
        const chapId = sourceKey.replace('chapter_', '');
        const matchedChap = chaptersById.get(chapId);

        if (!matchedChap || !matchedChap.is_published) return;

        const effectivePublishAt = matchedChap.publish_at || n.publish_at;
        if (!isChapterReleasedForUser(effectivePublishAt, isPlusSubscriber)) return;

        const parentSeries = seriesList.find((s: any) => s.slug === matchedChap.series_slug);
        if (!parentSeries || parentSeries.is_hidden || !isReleasedYet(parentSeries.publish_at)) {
          return;
        }

        const dedupeKey = `chapter_${chapId}`;
        if (isDismissed(String(n.id)) || isDismissed(dedupeKey)) return;

        unifiedMap.set(dedupeKey, {
          ...n,
          id: String(n.id),
          dedupeKey,
          chapter_id: matchedChap.id,
          link_target: parentSeries.slug,
          thumbnail_url: matchedChap.thumbnail_url || parentSeries.cover_url || n.thumbnail_url,
          publish_at: effectivePublishAt,
          created_at: matchedChap.created_at || n.created_at
        });
      } else if (sourceKey.startsWith('series_')) {
        const sSlug = sourceKey.replace('series_', '');
        const matchedSeries = seriesList.find((s: any) => s.slug === sSlug);
        if (!matchedSeries || matchedSeries.is_hidden) return;

        const effectivePublishAt = matchedSeries.publish_at || n.publish_at;
        if (!isReleasedYet(effectivePublishAt)) return;

        const dedupeKey = `series_${sSlug}`;
        if (isDismissed(String(n.id)) || isDismissed(dedupeKey)) return;

        unifiedMap.set(dedupeKey, {
          ...n,
          id: String(n.id),
          dedupeKey,
          link_target: matchedSeries.slug,
          thumbnail_url: matchedSeries.cover_url || matchedSeries.character_url || n.thumbnail_url,
          publish_at: effectivePublishAt,
          created_at: matchedSeries.created_at || n.created_at
        });
      } else {
        if (isDismissed(String(n.id))) return;
        if (!isChapterReleasedForUser(n.publish_at, isPlusSubscriber)) return;

        if (n.link_target && !n.link_target.startsWith('http') && n.link_target !== 'news') {
          const matchedSeries = seriesList.find((s: any) => s.slug === n.link_target);
          if (
            matchedSeries &&
            (matchedSeries.is_hidden || !isReleasedYet(matchedSeries.publish_at))
          ) {
            return;
          }
        }

        unifiedMap.set(`custom_${n.id}`, {
          ...n,
          id: String(n.id),
          dedupeKey: `custom_${n.id}`
        });
      }
    });

    // 2A. Live Chapter Drops from `visibleLatestChapters`
    visibleLatestChapters.forEach((ch: any) => {
      const dedupeKey = `chapter_${ch.id}`;
      if (unifiedMap.has(dedupeKey) || isDismissed(dedupeKey) || isDismissed(String(ch.id))) return;

      const parentSeries = seriesList.find((s: any) => s.slug === ch.series_slug);
      if (!parentSeries) return;

      const alreadyHasManualMatch = Array.from(unifiedMap.values()).some(
        existing =>
          existing.link_target === parentSeries.slug &&
          String(existing.message || '').includes(`Chapter ${ch.chapter_number}`)
      );
      if (alreadyHasManualMatch) return;

      const isEarly = isInPlusEarlyAccessWindow(ch.publish_at);

      unifiedMap.set(dedupeKey, {
        id: dedupeKey,
        dedupeKey,
        chapter_id: ch.id,
        title: isEarly ? '⚡ 12H Early Access Drop!' : 'New Chapter Drop!',
        message: `${parentSeries.title} • Chapter ${ch.chapter_number}${
          ch.title ? `: "${ch.title}"` : ''
        } is now live!`,
        thumbnail_url: ch.thumbnail_url || parentSeries.cover_url || null,
        link_target: parentSeries.slug,
        publish_at: ch.publish_at || ch.created_at,
        created_at: ch.created_at
      });
    });

    // 2B. New Series Drops (Automatically synced from live `seriesList`)
    seriesList.forEach((s: any) => {
      if (!s?.slug || s.is_hidden || !isReleasedYet(s.publish_at)) return;
      const effectiveSeriesDate = s.publish_at || s.created_at;
      if (!isRecentAddition(effectiveSeriesDate, 14)) return;

      const dedupeKey = `series_${s.slug}`;
      if (unifiedMap.has(dedupeKey) || isDismissed(dedupeKey)) return;

      const hasCustomSeriesNotif = Array.from(unifiedMap.values()).some(
        existing =>
          existing.link_target === s.slug &&
          String(existing.title || '').toLowerCase().includes('series')
      );
      if (hasCustomSeriesNotif) return;

      unifiedMap.set(dedupeKey, {
        id: dedupeKey,
        dedupeKey,
        title: 'New Series Drop!',
        message: `${s.title}${
          s.creator_name ? ` by ${s.creator_name}` : ''
        } is now on Saturday AM! Tap to start reading.`,
        thumbnail_url: s.cover_url || s.character_url || null,
        link_target: s.slug,
        publish_at: effectiveSeriesDate,
        created_at: s.created_at || effectiveSeriesDate
      });
    });

    // 3. New Creators Added ("Meet the Creator" -> Jumps straight to Creator on CreatorsPage)
    const seenCreatorNames = new Set<string>();
    recentCreators.forEach((cr: any) => {
      if (!cr?.name || cr.is_visible === false) return;
      const cleanName = String(cr.name).trim();
      const normName = cleanName.toLowerCase();
      if (seenCreatorNames.has(normName)) return;
      seenCreatorNames.add(normName);

      if (!isRecentAddition(cr.created_at, 14)) return;

      const dedupeKey = `creator_${normName.replace(/\s+/g, '_')}`;
      if (unifiedMap.has(dedupeKey) || isDismissed(dedupeKey)) return;

      const parentSeries = seriesList.find((s: any) => s.slug === cr.series_slug);

      unifiedMap.set(dedupeKey, {
        id: dedupeKey,
        dedupeKey,
        title: 'Meet the Creator!',
        message: `${cleanName}${
          parentSeries?.title ? ` (${parentSeries.title})` : ''
        } has been added to the Creators Roster. Tap to view their bio & works!`,
        thumbnail_url:
          cr.avatar_url ||
          parentSeries?.creator_avatar ||
          parentSeries?.cover_url ||
          `${CLOUDFLARE_BASE_URL}/assets/creator-avatar.jpg`,
        navPayload: { action: 'creators', targetCreatorName: cleanName },
        publish_at: cr.created_at,
        created_at: cr.created_at
      });
    });

    // 4. New Characters Added ("New Character Unlocked!" -> Jumps straight to Character Dossier Modal)
    recentCharacters.forEach((ch: any) => {
      if (!ch?.id || !ch?.name || ch.is_hidden) return;
      if (!isRecentAddition(ch.created_at, 14)) return;

      const dedupeKey = `character_${ch.id}`;
      if (unifiedMap.has(dedupeKey) || isDismissed(dedupeKey)) return;

      const parentSeries = seriesList.find((s: any) => s.slug === ch.series_slug);

      unifiedMap.set(dedupeKey, {
        id: dedupeKey,
        dedupeKey,
        title: 'New Character Unlocked!',
        message: `${ch.name}${
          parentSeries?.title ? ` from ${parentSeries.title}` : ''
        } joined the Character Roster! Tap to inspect their combat file.`,
        thumbnail_url: ch.headshot_url || parentSeries?.cover_url || null,
        navPayload: {
          action: 'characters',
          targetCharacterId: ch.id,
          targetCharacterName: ch.name
        },
        publish_at: ch.created_at,
        created_at: ch.created_at
      });
    });

    // 5. New Card Skins Added (-> Jumps straight to Profile Loadout -> Hype Card tab)
    (cardSkins || []).forEach((skin: any) => {
      if (!skin?.id || skin.is_active === false) return;
      if (!isRecentAddition(skin.created_at, 14)) return;

      const dedupeKey = `skin_${skin.id}`;
      if (unifiedMap.has(dedupeKey) || isDismissed(dedupeKey)) return;

      unifiedMap.set(dedupeKey, {
        id: dedupeKey,
        dedupeKey,
        title: 'New Hype Card Skin!',
        message: `The "${skin.name}" Hype Card skin is now available in the Vault! Tap to equip it to your pass.`,
        thumbnail_url: skin.image_url || null,
        navPayload: { action: 'profile', openLoadoutTab: 'card' },
        publish_at: skin.created_at,
        created_at: skin.created_at
      });
    });

    // 6. New Avatars Added (-> Jumps straight to Profile Loadout -> Avatar Art tab)
    (vaultAvatars || []).forEach((av: any) => {
      if (!av?.id) return;
      if (!isRecentAddition(av.created_at, 14)) return;

      const dedupeKey = `avatar_${av.id}`;
      if (unifiedMap.has(dedupeKey) || isDismissed(dedupeKey)) return;

      unifiedMap.set(dedupeKey, {
        id: dedupeKey,
        dedupeKey,
        title: 'New Avatar Art Added!',
        message: `New "${
          av.name || 'Character'
        }" avatar art is live! Tap to customize your profile avatar.`,
        thumbnail_url: av.image_url || null,
        navPayload: { action: 'profile', openLoadoutTab: 'art' },
        publish_at: av.created_at,
        created_at: av.created_at
      });
    });

    // 7. New Border Frames Added (-> Jumps straight to Profile Loadout -> Border Frame tab)
    (vaultFrames || []).forEach((fr: any) => {
      if (!fr?.id || fr.is_active === false) return;
      if (!isRecentAddition(fr.created_at, 14)) return;

      const dedupeKey = `frame_${fr.id}`;
      if (unifiedMap.has(dedupeKey) || isDismissed(dedupeKey)) return;

      unifiedMap.set(dedupeKey, {
        id: dedupeKey,
        dedupeKey,
        title: 'New Border Frame Added!',
        message: `The "${fr.name}" (${
          fr.tier || 'Basic'
        }) border frame has been added! Tap to preview & equip it.`,
        thumbnail_url: `${CLOUDFLARE_BASE_URL}/other%20icons/Hype%20flame.png`,
        navPayload: { action: 'profile', openLoadoutTab: 'frame' },
        publish_at: fr.created_at,
        created_at: fr.created_at
      });
    });

    // 8. Automatic Weekly Reminders: One-Shot Wednesdays (Wed) & Early Access Reminder (Fri)
    const nowDate = new Date(nowTick);
    const dayOfWeek = nowDate.getDay(); // 0=Sun, 3=Wed, 5=Fri, 6=Sat
    const todayDateKey = nowDate.toISOString().split('T')[0];

    // 8A. ONE-SHOT WEDNESDAY (Every Wednesday)
    if (dayOfWeek === 3) {
      const oswKey = `osw_wed_${todayDateKey}`;
      if (!isDismissed(oswKey)) {
        const featuredOsw = getOneShotWednesdaySeries(seriesList, nowDate);
        const wedMorningIso = new Date(
          nowDate.getFullYear(),
          nowDate.getMonth(),
          nowDate.getDate(),
          9,
          0,
          0
        ).toISOString();

        unifiedMap.set(oswKey, {
          id: oswKey,
          dedupeKey: oswKey,
          title: '🔥 One-Shot Wednesday!',
          message: featuredOsw
            ? `Read "${featuredOsw.title}" FREE for 24 hours today for One-Shot Wednesday! Tap to read now.`
            : 'One-Shot Wednesday is LIVE! Enjoy 24-hour free access to our featured One-Shot today.',
          thumbnail_url:
            featuredOsw?.cover_url || `${CLOUDFLARE_BASE_URL}/other%20icons/Hype%20flame.png`,
          link_target: featuredOsw ? featuredOsw.slug : 'browse',
          publish_at: wedMorningIso,
          created_at: wedMorningIso
        });
      }
    }

    // 8B. FRIDAY REMINDER FOR SATURDAY 12-HOUR EARLY ACCESS (Every Friday)
    if (dayOfWeek === 5) {
      const friKey = `friday_early_access_${todayDateKey}`;
      if (!isDismissed(friKey)) {
        const friMorningIso = new Date(
          nowDate.getFullYear(),
          nowDate.getMonth(),
          nowDate.getDate(),
          10,
          0,
          0
        ).toISOString();

        unifiedMap.set(friKey, {
          id: friKey,
          dedupeKey: friKey,
          title: '⚡ Saturday Early Access Reminder!',
          message: isPlusSubscriber
            ? 'Your 12-Hour PLUS Early Access window for Saturday chapter drops opens tonight! Get ready to read first.'
            : 'Saturday AM+ members unlock new Saturday chapters 12 hours early! Tap to upgrade for $1.99/mo.',
          thumbnail_url: `${CLOUDFLARE_BASE_URL}/other%20icons/Hype%20flame.png`,
          navPayload: isPlusSubscriber ? { action: 'browse' } : { action: 'sub' },
          publish_at: friMorningIso,
          created_at: friMorningIso
        });
      }
    }

    return Array.from(unifiedMap.values())
      .sort((a, b) => {
        const timeA = new Date(a.publish_at || a.created_at || 0).getTime();
        const timeB = new Date(b.publish_at || b.created_at || 0).getTime();
        return timeB - timeA;
      })
      .slice(0, 20);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    notifications,
    visibleLatestChapters,
    latestChapters,
    recentCreators,
    recentCharacters,
    cardSkins,
    vaultAvatars,
    vaultFrames,
    seriesList,
    dismissedNotifs,
    nowTick,
    isPlusSubscriber
  ]);

  const fetchGlobalNotifications = async () => {
    try {
      const { data: notifData } = await supabase
        .from('app_notifications')
        .select('*')
        .order('created_at', { ascending: false })
        .limit(40);
      if (notifData) {
        const validData = notifData.filter(n => n && n.id && n.title);
        setNotifications(validData);
        memNotifications = validData;
      }
    } catch (e) {
      console.error('Error fetching notifs:', e);
    }
  };

  useEffect(() => {
    const savedDismissed = JSON.parse(localStorage.getItem('am_dismissed_notifs') || '[]');
    setDismissedNotifs(savedDismissed);

    const fetchHomeData = async (force = false) => {
      if (
        !force &&
        memHeroSlides &&
        memHomeSections &&
        memLatestChapters &&
        Date.now() - lastHomeFetchTime < 3 * 60 * 1000
      ) {
        setHeroSlides(memHeroSlides);
        setHomeSections(memHomeSections);
        setLatestChapters(memLatestChapters);
        if (memRecentCreators) setRecentCreators(memRecentCreators);
        if (memRecentCharacters) setRecentCharacters(memRecentCharacters);
        setIsLoadingSlides(false);
        return;
      }

      try {
        const [
          { data: slideData },
          { data: sectionData },
          { data: chapData },
          { data: creatorsData },
          { data: charsData }
        ] = await Promise.all([
          supabase.from('hero_slides').select('*').order('id', { ascending: true }),
          supabase.from('home_sections').select('*').order('display_order', { ascending: true }),
          supabase
            .from('chapters')
            .select('*')
            .eq('is_published', true)
            .order('created_at', { ascending: false })
            .limit(200),
          supabase.from('series_creators').select('*').order('id', { ascending: false }).limit(30),
          supabase.from('series_characters').select('*').order('id', { ascending: false }).limit(30)
        ]);

        if (slideData) {
          setHeroSlides(slideData);
          memHeroSlides = slideData;
        }

        if (sectionData) {
          setHomeSections(sectionData);
          memHomeSections = sectionData;
        }

        if (chapData) {
          setLatestChapters(chapData);
          memLatestChapters = chapData;
        }

        if (creatorsData) {
          setRecentCreators(creatorsData);
          memRecentCreators = creatorsData;
        }

        if (charsData) {
          setRecentCharacters(charsData);
          memRecentCharacters = charsData;
        }

        await fetchGlobalNotifications();
        lastHomeFetchTime = Date.now();
      } catch (err: any) {
        console.error('Error fetching home data:', err.message);
      } finally {
        setIsLoadingSlides(false);
      }
    };

    fetchHomeData();

    const handleSeriesOrChaptersUpdated = () => {
      fetchHomeData(true);
    };

    const handleVisibilityRefresh = () => {
      if (
        document.visibilityState === 'visible' &&
        Date.now() - lastHomeFetchTime > 5 * 60 * 1000
      ) {
        fetchHomeData(true);
      }
    };

    window.addEventListener('seriesUpdated', handleSeriesOrChaptersUpdated);
    document.addEventListener('visibilitychange', handleVisibilityRefresh);
    return () => {
      window.removeEventListener('seriesUpdated', handleSeriesOrChaptersUpdated);
      document.removeEventListener('visibilitychange', handleVisibilityRefresh);
    };
  }, []);

  useEffect(() => {
    if (showNotifications) fetchGlobalNotifications();
  }, [showNotifications]);

  const handleDismissNotif = (e: React.MouseEvent, notif: any) => {
    e.stopPropagation();
    const keysToDismiss = [String(notif.id), String(notif.dedupeKey || '')].filter(Boolean);
    const updated = Array.from(new Set([...dismissedNotifs, ...keysToDismiss]));
    setDismissedNotifs(updated);
    localStorage.setItem('am_dismissed_notifs', JSON.stringify(updated));
  };

  const handleClearAllNotifs = (e: React.MouseEvent) => {
    e.stopPropagation();
    const allLoadedIds = visibleNotifications.flatMap(n =>
      [String(n.id), String(n.dedupeKey || '')].filter(Boolean)
    );
    const updated = Array.from(new Set([...dismissedNotifs, ...allLoadedIds]));
    setDismissedNotifs(updated);
    localStorage.setItem('am_dismissed_notifs', JSON.stringify(updated));
  };

  // Smart click router for notifications (handles deep-links to Creators, Characters, Profile Loadout Tabs, Chapters & Series)
  const handleNotificationClick = (n: any) => {
    setShowNotifications(false);

    // 1. Direct structured navigation payload
    if (n.navPayload) {
      if (n.navPayload.targetCreatorName) {
        sessionStorage.setItem('am_target_creator', n.navPayload.targetCreatorName);
      }
      if (n.navPayload.targetCharacterId) {
        sessionStorage.setItem('am_target_character_id', String(n.navPayload.targetCharacterId));
      }
      if (n.navPayload.targetCharacterName) {
        sessionStorage.setItem(
          'am_target_character_name',
          String(n.navPayload.targetCharacterName)
        );
      }
      if (n.navPayload.openLoadoutTab) {
        sessionStorage.setItem('am_open_loadout_tab', String(n.navPayload.openLoadoutTab));
      }
      onNavigate(n.navPayload);
      return;
    }

    // 2. Legacy / Manual `link_target` string support (including `creator:Name`, `character:ID`, `loadout:tab`)
    if (n.link_target) {
      const target = String(n.link_target).trim();
      if (target.startsWith('http')) {
        window.open(target, '_blank');
        return;
      }
      if (target.toLowerCase().startsWith('creator:')) {
        const cName = target.slice(8).trim();
        sessionStorage.setItem('am_target_creator', cName);
        onNavigate({ action: 'creators', targetCreatorName: cName });
        return;
      }
      if (target.toLowerCase().startsWith('character:')) {
        const cId = target.slice(10).trim();
        sessionStorage.setItem('am_target_character_id', cId);
        sessionStorage.setItem('am_target_character_name', cId);
        onNavigate({ action: 'characters', targetCharacterId: cId });
        return;
      }
      if (target.toLowerCase().startsWith('loadout:')) {
        const tab = target.slice(8).trim();
        sessionStorage.setItem('am_open_loadout_tab', tab);
        onNavigate({ action: 'profile', openLoadoutTab: tab });
        return;
      }

      const matchedSeries = seriesList.find((s: any) => s.slug === target);
      if (matchedSeries && !matchedSeries.is_hidden) {
        onNavigate(
          n.chapter_id ? { ...matchedSeries, autoOpenChapterId: n.chapter_id } : matchedSeries
        );
      } else {
        onNavigate({ action: target });
      }
    }
  };

  useEffect(() => {
    const fetchRecentReads = async () => {
      if (isLoading || !currentUser) {
        setRecentReads([]);
        return;
      }
      if (memRecentReads) {
        setRecentReads(memRecentReads);
        return;
      }

      try {
        const { data: history } = await supabase
          .from('reading_history')
          .select('*')
          .eq('user_id', currentUser.id)
          .order('updated_at', { ascending: false })
          .limit(10);
        if (!history || history.length === 0) return;

        const allIds = history.map((h: any) => h.chapter_id);
        let chapters: any[] = [];

        if (allIds.length > 0) {
          const { data: chapterData } = await supabase.from('chapters').select('*').in('id', allIds);
          if (chapterData) chapters = chapterData;
        }

        const combined = history
          .map((h: any) => {
            const chap = chapters.find((c: any) => String(c.id) === String(h.chapter_id));

            if (
              chap &&
              chap.is_published &&
              isChapterReleasedForUser(chap.publish_at, isPlusSubscriber)
            ) {
              const series = seriesList.find((s: any) => s.slug === chap.series_slug);
              if (!series || series.is_hidden || !isReleasedYet(series.publish_at)) return null;
              return {
                ...h,
                type: 'series',
                target: { ...series, action: 'series' },
                title: series.title,
                subtitle: `Chapter ${chap.chapter_number}`,
                image: chap.thumbnail_url || series.cover_url
              };
            }
            return null;
          })
          .filter(Boolean);

        setRecentReads(combined);
        memRecentReads = combined;
      } catch (err: any) {
        console.error('Critical Error fetching recent reads:', err);
      }
    };

    fetchRecentReads();
  }, [seriesList, isLoading, currentUser, isPlusSubscriber]);

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentSlide(prev => (heroSlides.length > 0 ? (prev + 1) % heroSlides.length : 0));
    }, 5000);
    return () => clearInterval(timer);
  }, [heroSlides.length]);

  useEffect(() => {
    const handleInstantLogout = () => {
      memRecentReads = null;
      setRecentReads([]);
    };
    window.addEventListener('instantLogout', handleInstantLogout);
    return () => window.removeEventListener('instantLogout', handleInstantLogout);
  }, []);

  const handleSlideClick = (slide: any) => {
    trackEvent('banner_click', { target: slide.link_target, link_type: slide.link_type });

    if (!slide.link_target) return;
    if (slide.link_type === 'external')
      window.open(slide.link_target, '_blank', 'noopener,noreferrer');
    else if (slide.link_type === 'series') {
      const matchedSeries = seriesList.find((s: any) => s.slug === slide.link_target);
      if (matchedSeries && !matchedSeries.is_hidden && isReleasedYet(matchedSeries.publish_at))
        onNavigate(matchedSeries);
    }
  };

  // Maps each series_slug to its earliest upcoming scheduled chapter publish_at timestamp
  const nextScheduledBySeries = useMemo(() => {
    const map: Record<string, string> = {};
    latestChapters.forEach((ch: any) => {
      if (!ch.is_published || !ch.publish_at) return;
      if (!isChapterReleasedForUser(ch.publish_at, isPlusSubscriber)) {
        const existing = map[ch.series_slug];
        if (!existing || new Date(ch.publish_at).getTime() < new Date(existing).getTime()) {
          map[ch.series_slug] = ch.publish_at;
        }
      }
    });
    return map;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [latestChapters, isPlusSubscriber, nowTick]);

  // --- UPDATED LARGE HYPE FLAME LOADER FOR HOMEPAGE ---
  if (isLoading || isLoadingSlides) {
    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center gap-4">
        <svg className="absolute w-0 h-0 pointer-events-none" aria-hidden="true">
          <filter id="hype-flame-color" colorInterpolationFilters="sRGB">
            <feColorMatrix
              type="matrix"
              values="
                0.004  0      0      0.996  0
                0      0.396  0      0.604  0
                0      0      1      0      0
                0      0      0      1      0"
            />
          </filter>
        </svg>

        <div className="relative flex items-center justify-center animate-hype-glow">
          <img
            src="https://pub-180171f859f64aa7aadb7001a6b96e65.r2.dev/other%20icons/Hype%20flame.png"
            alt="Saturday AM Loading"
            className="w-24 h-24 sm:w-28 sm:h-28 object-contain"
            style={{ filter: 'url(#hype-flame-color)' }}
          />
        </div>
      </div>
    );
  }

  return (
    <div className="relative min-h-screen bg-transparent text-white pb-24">
      <FeatureTutorialModal
        tutorialId="home_page_basics"
        slides={homeTutorialSlides}
        forceOpen={forceTutorial}
        onClose={() => setForceTutorial(false)}
      />

      <div className="fixed inset-0 z-[-1] bg-black">
        <img
          src="https://pub-180171f859f64aa7aadb7001a6b96e65.r2.dev/homepage-graphic-assets/AM%20App%20Backdrop%20narrow.png"
          alt="Manga Collage"
          className="w-full h-full object-cover md:hidden"
        />
        <img
          src="https://pub-180171f859f64aa7aadb7001a6b96e65.r2.dev/homepage-graphic-assets/AM%20App%20Backdrop%20wide.png"
          alt="Manga Collage"
          className="hidden md:block w-full h-full object-cover"
        />
        <div className="absolute inset-x-0 top-0 h-48 sm:h-64 bg-gradient-to-b from-black via-black/50 to-transparent pointer-events-none" />
        <div className="absolute inset-x-0 bottom-0 h-48 sm:h-64 bg-gradient-to-t from-black via-black/80 to-transparent pointer-events-none" />
      </div>

      <nav className="sticky top-0 w-full z-[100] px-4 py-3 sm:px-6 sm:py-4 flex justify-between items-center bg-black/80 backdrop-blur-xl border-b border-white/5 shadow-2xl mb-8">
        <div
          className="flex items-center cursor-pointer flex-shrink-0"
          onClick={() => onNavigate({ action: 'home' })}
        >
          <img
            src="https://pub-180171f859f64aa7aadb7001a6b96e65.r2.dev/homepage-graphic-assets/logos/SATURDAY%20AM%20Logo.png"
            alt="Saturday AM"
            className="h-10 md:h-12 object-contain drop-shadow-md hover:scale-105 transition-transform"
          />
        </div>

        <div className="flex items-center justify-end gap-2 sm:gap-3">
          {!currentUser ? (
            <button
              onClick={onLoginClick}
              className="whitespace-nowrap flex-shrink-0 flex items-center justify-center bg-[#fe9a00] text-black px-4 py-1.5 sm:px-5 sm:py-2 rounded-full font-black uppercase tracking-widest text-[9px] sm:text-[10px] hover:bg-white transition-colors shadow-[0_0_15px_rgba(254,154,0,0.3)] cursor-pointer"
            >
              Log In
            </button>
          ) : (
            <div
              className="hidden sm:flex items-center gap-2 cursor-pointer hover:opacity-80 transition-opacity mr-1"
              onClick={() => onNavigate({ action: 'profile' })}
            >
              <DecoratedAvatar
                avatarUrl={currentUser.avatar_url}
                frameId={currentUser.frame_id}
                size="w-8 h-8"
                iconSize="w-4 h-4"
              />
              {userTier === 'premium' && (
                <span className="bg-purple-900/40 border border-purple-500 text-purple-400 px-1.5 py-0.5 rounded text-[8px] sm:text-[9px] font-black tracking-widest uppercase ml-1 animate-fade-in">
                  PLUS
                </span>
              )}
            </div>
          )}

          {/* 1-TAP UNIVERSAL HARD REFRESH BUTTON */}
          <button
            type="button"
            onClick={handleHardRefresh}
            disabled={isRefreshingApp}
            className="p-2 bg-zinc-900 border border-zinc-700 rounded-full hover:bg-[#fe9a00] hover:border-[#fe9a00] group transition-all cursor-pointer"
            title="Refresh App & Clear Cache"
            aria-label="Refresh App"
          >
            <RefreshCw
              className={`w-4 h-4 sm:w-5 sm:h-5 text-zinc-400 group-hover:text-black transition-colors ${
                isRefreshingApp ? 'animate-spin text-[#fe9a00]' : ''
              }`}
            />
          </button>

          <div className="relative">
            <button
              onClick={() => setShowNotifications(!showNotifications)}
              className="p-2 bg-zinc-900 border border-zinc-700 rounded-full hover:bg-[#fe9a00] hover:border-[#fe9a00] group transition-all relative cursor-pointer"
            >
              <Bell className="w-4 h-4 sm:w-5 sm:h-5 text-zinc-400 group-hover:text-black transition-colors" />
              {visibleNotifications.length > 0 && (
                <span className="absolute top-0 right-0 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-zinc-900 animate-pulse" />
              )}
            </button>
            {showNotifications && (
              <>
                <div className="fixed inset-0 z-[190]" onClick={() => setShowNotifications(false)} />
                <div className="absolute top-full mt-2 right-0 w-72 sm:w-80 bg-zinc-900 border border-zinc-800 rounded-2xl shadow-2xl overflow-hidden z-[200] animate-fade-in-up">
                  <div className="p-4 border-b border-zinc-800 flex justify-between items-center bg-black/50">
                    <h3 className="font-black italic uppercase text-white tracking-widest text-sm">
                      Updates
                    </h3>
                    <div className="flex items-center gap-3">
                      {visibleNotifications.length > 0 && (
                        <button
                          onClick={handleClearAllNotifs}
                          className="text-[9px] text-zinc-500 hover:text-white uppercase tracking-widest font-black transition-colors cursor-pointer"
                        >
                          Clear All
                        </button>
                      )}
                      <button
                        onClick={() => setShowNotifications(false)}
                        className="text-zinc-500 hover:text-white transition-colors cursor-pointer"
                        title="Close"
                      >
                        <X className="w-4 h-4 sm:w-5 sm:h-5" />
                      </button>
                    </div>
                  </div>
                  <div className="max-h-96 min-h-[120px] overflow-y-auto no-scrollbar relative bg-black/20">
                    {visibleNotifications.length === 0 ? (
                      <div className="absolute inset-0 flex flex-col items-center justify-center p-6 text-center">
                        <CheckCircle className="w-8 h-8 text-zinc-700 mb-3" />
                        <span className="text-zinc-500 font-bold text-[10px] uppercase tracking-widest leading-relaxed">
                          You're all caught up
                        </span>
                      </div>
                    ) : (
                      visibleNotifications.map(n => {
                        const effectiveTime = n.publish_at || n.created_at;
                        const dateLabel = effectiveTime
                          ? new Date(effectiveTime).toLocaleDateString('en-US', {
                              month: 'short',
                              day: 'numeric'
                            })
                          : '';

                        return (
                          <div
                            key={n.id}
                            onClick={() => handleNotificationClick(n)}
                            className="relative group p-4 border-b border-zinc-800/50 hover:bg-zinc-800 cursor-pointer flex gap-3.5 transition-colors pr-10"
                          >
                            <button
                              onClick={e => handleDismissNotif(e, n)}
                              className="absolute top-2 right-2 p-1.5 text-zinc-600 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity rounded-full hover:bg-black/50 z-10 cursor-pointer"
                              title="Dismiss"
                            >
                              <X className="w-4 h-4" />
                            </button>
                            {n.thumbnail_url && (
                              <img
                                src={n.thumbnail_url}
                                className="w-12 h-12 rounded object-cover flex-shrink-0 border border-zinc-700 bg-black"
                                alt="Notification"
                              />
                            )}
                            <div className="flex flex-col justify-center w-full min-w-0">
                              <div className="flex items-center gap-1.5">
                                <span className="text-white font-black text-xs uppercase tracking-wider leading-tight group-hover:text-[#fe9a00] transition-colors truncate">
                                  {n.title}
                                </span>
                                {isNewRelease(n.publish_at, n.created_at) && (
                                  <span className="bg-red-600 text-white text-[7px] font-black uppercase px-1 py-0.5 rounded shrink-0">
                                    NEW
                                  </span>
                                )}
                              </div>
                              <span className="text-zinc-300 text-[10px] font-bold mt-1 line-clamp-2 leading-relaxed">
                                {n.message}
                              </span>
                              {dateLabel && (
                                <span className="text-[8px] font-black uppercase tracking-widest text-zinc-500 mt-1">
                                  {dateLabel}
                                </span>
                              )}
                            </div>
                          </div>
                        );
                      })
                    )}
                  </div>
                </div>
              </>
            )}
          </div>

          <button
            onClick={onMenuToggle}
            className="p-2 bg-zinc-900 border border-zinc-700 hover:bg-[#fe9a00] hover:border-[#fe9a00] group rounded-full transition-colors cursor-pointer"
          >
            <Menu className="w-4 h-4 sm:w-5 sm:h-5 text-zinc-400 group-hover:text-black transition-colors" />
          </button>
        </div>
      </nav>

      <div className="px-6">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-2xl md:text-3xl font-black italic uppercase text-white drop-shadow-md">
            Discover
          </h1>
          <TutorialHelpButton onClick={() => setForceTutorial(true)} />
        </div>

        <div className="mb-8 w-full flex flex-col items-center">
          <div className="w-full relative overflow-hidden rounded-lg mb-4 aspect-[2/3] md:aspect-[3/1] bg-zinc-900/80 border border-zinc-800/50 shadow-xl backdrop-blur-sm">
            {heroSlides.map((slide, index) => (
              <div
                key={slide.id}
                onClick={() => handleSlideClick(slide)}
                className={`absolute inset-0 transition-opacity duration-1000 ease-in-out cursor-pointer ${
                  index === currentSlide ? 'opacity-100 z-10' : 'opacity-0 z-0'
                }`}
              >
                <img
                  src={slide.mobile_url}
                  alt={`Slide ${index}`}
                  className="md:hidden w-full h-full object-cover"
                />
                <img
                  src={slide.desktop_url}
                  alt={`Slide ${index}`}
                  className="hidden md:block w-full h-full object-cover"
                />
              </div>
            ))}
            {heroSlides.length > 1 && (
              <div className="absolute bottom-4 left-0 right-0 z-20 flex justify-center gap-2">
                {heroSlides.map((_, index) => (
                  <button
                    key={index}
                    onClick={e => {
                      e.stopPropagation();
                      setCurrentSlide(index);
                    }}
                    className={`h-1.5 rounded-full transition-all duration-300 ${
                      index === currentSlide
                        ? 'bg-[#fe9a00] w-6'
                        : 'bg-white/50 w-1.5 hover:bg-white'
                    }`}
                  />
                ))}
              </div>
            )}
          </div>
        </div>

        {visibleLatestChapters.length > 0 && (
          <div className="mb-10 relative group px-2">
            <div className="flex items-center gap-3 mb-4">
              <svg
                className="w-5 h-5 text-[#fe9a00] ml-1 drop-shadow-[0_0_8px_rgba(254,154,0,0.8)]"
                viewBox="0 0 24 24"
                fill="currentColor"
              >
                <polygon points="0,0 8,0 8,24 0,24" />
                <polygon points="10,0 24,0 24,14 10,8" />
                <polygon points="10,10 24,16 24,24 10,24" />
              </svg>
              <h2 className="text-xl font-black text-white tracking-wider uppercase drop-shadow-md">
                Latest Chapters
              </h2>
            </div>

            <div className="flex overflow-x-auto gap-4 pb-4 snap-x no-scrollbar items-start">
              {visibleLatestChapters.map(chapter => {
                const seriesData =
                  seriesList.find((s: any) => s.slug === chapter.series_slug) || {};
                const isEarlyAccess = isInPlusEarlyAccessWindow(chapter.publish_at);
                const showNewBadge = isNewRelease(chapter.publish_at, chapter.created_at);

                return (
                  <div
                    key={chapter.id}
                    onClick={() =>
                      onNavigate({ ...seriesData, autoOpenChapterId: chapter.id })
                    }
                    className="w-[45%] sm:w-[35%] md:w-[25%] flex-shrink-0 cursor-pointer group/card snap-start flex flex-col"
                  >
                    <div className="relative overflow-hidden rounded-lg aspect-square border-[1px] border-[#fe9a00]/50 shadow-[0_0_20px_rgba(254,154,0,0.4)] group-hover/card:-translate-y-1 group-hover/card:border-[#fe9a00] group-hover/card:shadow-[0_0_30px_rgba(254,154,0,0.8)] transition-all duration-300">
                      <img
                        src={
                          chapter.thumbnail_url ||
                          seriesData.cover_url ||
                          'https://pub-180171f859f64aa7aadb7001a6b96e65.r2.dev/assets/placeholder-thumb.jpg'
                        }
                        className="w-full h-full object-cover"
                        style={{
                          objectPosition: chapter.thumbnail_position || '50% 50%',
                          transform: `scale(${(chapter.thumbnail_scale || 100) / 100})`
                        }}
                        alt="Chapter Thumbnail"
                      />
                      <div className="absolute bottom-0 inset-x-0 bg-gradient-to-t from-black via-black/80 to-transparent p-3 pt-12">
                        <p className="text-[#fe9a00] font-black text-[10px] uppercase tracking-widest drop-shadow-[0_0_5px_rgba(254,154,0,0.8)]">
                          CH. {chapter.chapter_number}
                        </p>
                      </div>
                      {isEarlyAccess ? (
                        <div className="absolute top-1.5 right-1.5 z-30 bg-gradient-to-r from-purple-600 to-[#fe9a00] text-white text-[8px] font-black uppercase tracking-widest px-1.5 py-0.5 rounded shadow-[0_0_10px_rgba(168,85,247,0.8)] animate-pulse pointer-events-none">
                          ⚡ 12H EARLY ACCESS
                        </div>
                      ) : (
                        showNewBadge && (
                          <div className="absolute top-1.5 right-1.5 z-30 bg-red-600 text-white text-[8px] font-black uppercase tracking-widest px-1.5 py-0.5 rounded shadow-[0_0_10px_rgba(220,38,38,0.8)] animate-pulse pointer-events-none">
                            NEW!
                          </div>
                        )
                      )}
                    </div>

                    <div className="mt-3 px-1 flex flex-col flex-1">
                      <h3 className="text-white font-bold text-xs truncate group-hover/card:text-[#fe9a00] transition-colors">
                        {seriesData.title}
                      </h3>
                      <p className="text-zinc-400 text-[10px] font-bold truncate mt-0.5">
                        {chapter.title || `Chapter ${chapter.chapter_number}`}
                      </p>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {recentReads.length > 0 && (
          <div className="mb-12 animate-fade-in bg-black/40 backdrop-blur-sm p-4 rounded-xl border border-zinc-800/50">
            <h2 className="text-xl md:text-2xl font-black italic uppercase tracking-wider text-white mb-4 px-2 drop-shadow-md">
              Jump Back In
            </h2>
            <div className="flex gap-4 overflow-x-auto pb-4 px-2 no-scrollbar">
              {recentReads.map(read => (
                <div
                  key={read.id}
                  onClick={() =>
                    onNavigate({
                      ...read.target,
                      autoOpenChapterId: read.chapter_id,
                      autoOpenPage: read.page_index
                    })
                  }
                  className="relative min-w-[140px] w-[140px] md:min-w-[180px] md:w-[180px] aspect-[2/3] rounded-xl overflow-hidden cursor-pointer group border-[1px] border-white shadow-[5px_5px_0px_0px_#fe9a00] hover:shadow-[8px_8px_0px_0px_#fe9a00] hover:-translate-y-1 hover:-translate-x-1 transition-all duration-300 flex-shrink-0 mb-3"
                >
                  <img
                    src={read.image}
                    alt={read.title}
                    className="absolute inset-0 w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent flex flex-col justify-end p-3 z-10">
                    <h3 className="text-white font-black uppercase text-xs md:text-sm leading-tight line-clamp-1 drop-shadow-md">
                      {read.title}
                    </h3>
                    <div className="flex justify-between items-center mt-1">
                      <p className="text-[#fe9a00] font-bold text-[9px] md:text-[10px] uppercase tracking-widest drop-shadow-md">
                        {read.subtitle}
                      </p>
                      <p className="text-zinc-300 font-bold text-[8px] md:text-[9px] uppercase tracking-widest bg-black/60 px-1.5 py-0.5 rounded border border-zinc-700 backdrop-blur-sm">
                        Pg. {read.page_index + 1}
                      </p>
                    </div>
                  </div>
                  <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex items-center justify-center backdrop-blur-[2px] z-20">
                    <div className="w-12 h-12 md:w-14 md:h-14 rounded-full bg-[#fe9a00] flex items-center justify-center shadow-[0_0_20px_rgba(254,154,0,0.6)] transform scale-75 group-hover:scale-100 transition-transform duration-300">
                      <Play className="w-5 h-5 md:w-6 md:h-6 text-black ml-1" />
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {homeSections.map(section => {
          const seriesInSection = seriesList
            .filter(
              (s: any) =>
                s.home_section === section.title && !s.is_hidden && isReleasedYet(s.publish_at)
            )
            .sort((a: any, b: any) => (a.display_order || 99) - (b.display_order || 99));

          if (seriesInSection.length === 0) return null;
          return (
            <SeriesSection
              key={section.id}
              title={section.title}
              series={seriesInSection}
              onSeriesClick={onNavigate}
              currentUser={currentUser}
              userTier={userTier}
              nextScheduledBySeries={nextScheduledBySeries}
              onRequireAuth={onLoginClick}
            />
          );
        })}
      </div>
    </div>
  );
};
